<?php require __DIR__.'/../app/bootstrap.php'; require_login();
$no=trim((string)($_GET['asset_no']??''));$st=db()->prepare('SELECT a.*,p.full_name personnel_name,p.personnel_code FROM assets a LEFT JOIN personnel p ON p.id=a.personnel_id WHERE a.asset_no=?');$st->execute([$no]);$asset=$st->fetch();if(!$asset){http_response_code(404);exit('تجهیز یافت نشد.');}
$st=db()->prepare('SELECT * FROM asset_disks WHERE asset_no=? ORDER BY disk_index');$st->execute([$no]);$disks=$st->fetchAll();$st=db()->prepare('SELECT * FROM asset_ram_slots WHERE asset_no=? ORDER BY slot_no');$st->execute([$no]);$rams=$st->fetchAll();$tech=json_decode((string)$asset['technical'],true)?:[];$types=['computer'=>'رایانه','printer'=>'چاپگر','display'=>'نمایشگر','scanner'=>'اسکنر'];
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($asset['asset_no'])?> | تجهیز</title><link rel="stylesheet" href="assets/app.css"></head><body><header><a class="brand" href="index.php">سامانه سخت‌افزار</a><nav><a href="assets.php">تجهیزات</a><?php if((user()['role']??'')==='admin'):?><a href="audit.php">رویدادها</a><?php endif;?><a href="logout.php">خروج</a></nav></header><main><div class="page-head"><div><h1>پرونده تجهیز <?=e($asset['asset_no'])?></h1><p class="muted"><?=e($types[$asset['asset_type']]??$asset['asset_type'])?> · آخرین بروزرسانی <?=e($asset['updated_at'])?></p></div><?php if(can_edit_assets()):?><a class="btn primary" href="asset_edit.php?asset_no=<?=urlencode($no)">ویرایش</a><?php endif;?></div><section class="detail-grid"><article class="panel"><h2>مشخصات عمومی</h2><dl><dt>شماره اموال</dt><dd><?=e($asset['asset_no'])?></dd><dt>نام دستگاه</dt><dd><?=e($asset['hostname']?:'—')?></dd><dt>برند / مدل</dt><dd><?=e(trim(($asset['manufacturer']??'').' '.($asset['model']??''))?:'—')?></dd><dt>سریال</dt><dd><?=e($asset['serial_no']?:'—')?></dd><dt>پرسنل</dt><dd><?=e($asset['personnel_name']?:'—')?></dd><dt>کد پرسنلی</dt><dd><?=e($asset['personnel_code']?:'—')?></dd><dt>مکان</dt><dd><?=e($asset['location']?:'—')?></dd><dt>اداره / دانشکده</dt><dd><?=e($asset['department']?:'—')?></dd></dl></article><article class="panel"><h2>اطلاعات فنی</h2><?php foreach($tech as $k=>$v):?><div class="kv"><span><?=e($k)?></span><strong><?=e(is_array($v)?json_encode($v,JSON_UNESCAPED_UNICODE):str_replace('|',' | ',(string)$v))?></strong></div><?php endforeach;?></article></section><?php if($disks):?><section class="panel"><h2>ذخیره‌سازی / دیسک‌ها</h2><div class="table-wrap"><table><thead><tr><th>ردیف</th><th>مدل</th><th>ظرفیت GB</th><th>سریال</th><th>رابط</th><th>رسانه</th></tr></thead><tbody><?php foreach($disks as $d):?><tr><td><?=$d['disk_index']?></td><td><?=e($d['model'])?></td><td><?=e((string)$d['size_gb'])?></td><td><?=e($d['serial_no'])?></td><td><?=e($d['interface_name'])?></td><td><?=e($d['media'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?><?php if($rams):?><section class="panel"><h2>اسلات‌های RAM</h2><div class="table-wrap"><table><thead><tr><th>اسلات</th><th>وضعیت</th><th>ظرفیت</th><th>نوع</th><th>فرکانس</th><th>برند</th><th>Part Number</th><th>سریال</th></tr></thead><tbody><?php foreach($rams as $r):?><tr><td><?=e((string)$r['slot_no'])?></td><td><?=e($r['state'])?></td><td><?=e((string)$r['capacity_gb'])?></td><td><?=e($r['ram_type'])?></td><td><?=e((string)$r['speed_mhz'])?></td><td><?=e($r['manufacturer'])?></td><td><?=e($r['part_number'])?></td><td><?=e($r['serial_no'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?></main></body></html>
